// Camelot Streaming v13. Self-contained source installer; no network access.
import {readFileSync,writeFileSync,existsSync,mkdirSync,copyFileSync,renameSync,rmSync,lstatSync,readdirSync,chmodSync} from 'node:fs';
import {resolve,join,dirname,sep} from 'node:path';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
const payload="";
const root=process.cwd();
const check=process.argv.includes('--check');
function refuse(message){throw new Error(message)}
function safe(path){
 if(path.startsWith('/')||path.split('/').some(p=>!p||p==='.'||p==='..')||path.includes('\\')||path.includes(':'))refuse('Unsafe patch path');
 const target=resolve(root,...path.split('/'));
 if(!target.startsWith(root+sep))refuse('Patch path leaves project');
 let cursor=root;
 for(const part of path.split('/')){cursor=join(cursor,part);if(existsSync(cursor)&&lstatSync(cursor).isSymbolicLink())refuse('Move linked project files before updating: '+path)}
 return target;
}
try{
 const pkg=JSON.parse(readFileSync(join(root,'package.json'),'utf8'));
 if(pkg.name!=='camelot-bot')refuse('Open your camelot-bot folder before running this patch.');
 const entries=JSON.parse(gunzipSync(Buffer.from(payload,'base64')).toString());
 const paths=new Set();
 const changes=[];
 for(const entry of entries){
  const target=safe(entry.path);paths.add(entry.path);
  const data=Buffer.from(entry.data,'base64');
  if(createHash('sha256').update(data).digest('hex')!==entry.sha256)refuse('Patch integrity check failed.');
  if(existsSync(target)&&!lstatSync(target).isFile())refuse('Expected a file at '+entry.path);
  if(!existsSync(target)||!readFileSync(target).equals(data))changes.push({...entry,target,data,existed:existsSync(target)});
 }
 const obsolete=[];
 function walk(path){
  const absolute=safe(path);if(!existsSync(absolute))return;
  for(const item of readdirSync(absolute,{withFileTypes:true})){
   const child=path+'/'+item.name;safe(child);
   if(item.isDirectory())walk(child);else if(!paths.has(child))obsolete.push(child);
  }
 }
 walk('src');
 console.log(`${changes.length} file(s) to update; ${obsolete.length} old source file(s) to archive.`);
 if(check){console.log('Preview only. Run node patch.mjs to apply.');process.exit(0)}
 if(!changes.length&&!obsolete.length){console.log('Already up to date.');process.exit(0)}
 const backup=join(root,'.camelot-backup-'+new Date().toISOString().replace(/[:.]/g,'-'));
 mkdirSync(backup,{recursive:true});
 for(const entry of changes.filter(e=>e.existed)){
  const dest=join(backup,entry.path);mkdirSync(dirname(dest),{recursive:true});copyFileSync(entry.target,dest);
 }
 for(const path of obsolete){const dest=join(backup,path);mkdirSync(dirname(dest),{recursive:true});copyFileSync(safe(path),dest)}
 writeFileSync(join(backup,'restore.json'),JSON.stringify({replaced:changes.filter(e=>e.existed).map(e=>e.path),created:changes.filter(e=>!e.existed).map(e=>e.path),archived:obsolete},null,2));
 const written=[];
 try{
  for(const entry of changes){
   mkdirSync(dirname(entry.target),{recursive:true});
   const temp=entry.target+'.camelot-tmp';
   writeFileSync(temp,entry.data,{mode:entry.mode});
   written.push(entry);renameSync(temp,entry.target);
   if(process.platform!=='win32')chmodSync(entry.target,entry.mode);
  }
  for(const path of obsolete)rmSync(safe(path));
 }catch(error){
  for(const entry of written.reverse()){
   if(entry.existed)copyFileSync(join(backup,entry.path),entry.target);else rmSync(entry.target,{force:true});
   rmSync(entry.target+'.camelot-tmp',{force:true});
  }
  for(const path of obsolete)copyFileSync(join(backup,path),safe(path));
  throw error;
 }
 console.log('Updated Camelot Streaming. Backup: '+backup);
 console.log('Next: npm ci, npm test, then npm run build. Push only after they pass.');
}catch(error){console.error('Update stopped: '+error.message);process.exitCode=1}
